    const r = clamp01(0.5 + SH_C0_SOG * sh0Codebook[Math.round(c0[p])]);
    const g = clamp01(0.5 + SH_C0_SOG * sh0Codebook[Math.round(c0[p + 1])]);
    const bl = clamp01(0.5 + SH_C0_SOG * sh0Codebook[Math.round(c0[p + 2])]);
